// One line an evening, rotating with the day of the year, so the reminder does
// not read the same every time. The form writes straight into the Ore table: an
// evening without a form is a day without hours, and nothing needs filtering.
const LINES = [
  'Hours today? Thirty seconds and you are free.',
  'Did the business get a slice of today? Tell the form.',
  'Nothing today is a fine answer: just swipe me away.',
  'Write it down while you still remember it.',
  'A minute for the minutes.',
  'Genome, page, photos or office: where did today go?',
  'Future you, reading the January numbers, says thanks.',
];
const now = new Date();
const day = Math.floor((now - new Date(now.getFullYear(), 0, 0)) / 86400000);
const line = LINES[day % LINES.length];
const url = ($env.STUDIO_HOURS_FORM_URL || '').trim();

// Unset, there is no link to build: the message names the missing key instead
// of carrying a tap that opens nothing.
const payload = {
  topic: 'studio',
  title: 'Studio: hours',
  message: url ? line : `${line}\n\nSTUDIO_HOURS_FORM_URL is not set: no link to the form.`,
  tags: ['stopwatch'],
  priority: 3,
};
if (url) {
  payload.click = url;
  payload.actions = [{ action: 'view', label: 'Open the form', url }];
}
return [{ json: { payload } }];
